globalThis.KENGURU_CHOICE_LAYOUTS = {"2006-3-4/9":{"options":[{"image":"assets/separated-choice-vectors/2006-3-4/09-1.svg"},{"image":"assets/separated-choice-vectors/2006-3-4/09-2.svg"},{"image":"assets/separated-choice-vectors/2006-3-4/09-3.svg"},{"image":"assets/separated-choice-vectors/2006-3-4/09-4.svg"},{"image":"assets/separated-choice-vectors/2006-3-4/09-5.svg"}]},"2006-3-4/18":{"options":[{"image":"assets/separated-choice-vectors/2006-3-4/18-1.svg"},{"image":"assets/separated-choice-vectors/2006-3-4/18-2.svg"},{"image":"assets/separated-choice-vectors/2006-3-4/18-3.svg"},{"image":"assets/separated-choice-vectors/2006-3-4/18-4.svg"},{"image":"assets/separated-choice-vectors/2006-3-4/18-5.svg"}],"condition":{"src":"assets/separated-choices/2006-3-4/18-condition.webp","width":167,"height":147}},"2006-3-4/24":{"options":[{"text":"3 м"},{"text":"49 м"},{"text":"61 м"},{"text":"62 м"},{"text":"Все расстояния A–D возможны"}]}};
globalThis.KENGURU_LEGACY = [[2006,"3–4 классы",[[822,131,"Вася поет слово КЕНГУРУ. Он тянет каждый гласный звук 5 секунд, а на каждый согласный тратит ровно 1 секунду. Сколько времени он поет это слово?",{"0":[53.7,95.9,31.3,27.2],"1":[211.6,95.9,31.3,27.2],"2":[358.2,95.9,32.7,27.2],"3":[504.8,95.9,32.6,27.2],"4":[651.3,95.9,31.3,27.2]},"C","Вася поёт",[["Посчитай звуки","В слове КЕНГУРУ три гласных — Е, У, У, и четыре согласных — К, Н, Г, Р."],["Сложи секунды","На гласные уйдёт 3 × 5 = 15 секунд, на согласные — 4 × 1 = 4 секунды. Вместе 15 + 4 = 19 секунд."]],""],[822,124,"",{"0":[53.7,41.9,31.3,27.2],"1":[211.6,41.9,31.3,27.2],"2":[358.1,41.9,32.7,27.2],"3":[53.7,76,32.6,27.2],"4":[211.6,76,31.3,27.2]},"D","Сколько кубиков вынули",[["Посчитай слои","Сначала в каждом слое было по 3 × 3 = 9 кубиков. Нижний слой остался целым."],["Посмотри на верхний слой","Сверху оставили два угловых кубика. Вынули 9 − 2 = 7 кубиков."]],""],[822,104,"В кошельке у Сергея три монеты: 5 рублей, 2 рубля и 1 рубль. Какую сумму он не сможет заплатить без сдачи?",{"0":[53.7,68.9,31.3,27.2],"1":[191.7,68.9,31.3,27.2],"2":[331.6,68.9,32.7,27.2],"3":[484.8,68.9,32.6,27.2],"4":[638.1,68.9,31.3,27.2]},"B","Монеты без сдачи",[["Отложи пятирублёвую монету","С ней получится заплатить не меньше 5 рублей, поэтому для 4 рублей она не годится."],["Сложи мелкие монеты","Вместе монеты в 1 и 2 рубля дают только 3 рубля. Четыре рубля заплатить нельзя. Остальные суммы из вариантов можно собрать как 2 + 1, 5 + 1, 5 + 2 и 5 + 2 + 1."]],""],[822,200,"Кенгуру прошел через лабиринт, в котором один вход и пять выходов. Его маршрут проходил только по треугольным комнатам. Где он вышел?",{"0":[53.7,123,31.3,27.2],"1":[211.6,123,31.3,27.2],"2":[358.2,123,32.7,27.2],"3":[53.7,152.3,32.6,27.2],"4":[211.6,152.3,31.3,27.2]},"E","Треугольный лабиринт",[["Выбери первый проход","Из комнаты у входа бери верхний проход. Нижний ведёт в комнату с пятью сторонами. Через следующий верхний проход поднимись к треугольникам вдоль верхней границы."],["Иди по треугольникам","Следуй вправо через два треугольника у верхней границы, между ними проходя через маленький треугольник под ней. Затем спускайся через треугольники справа от середины схемы."],["Найди выход","Из большого треугольника внизу справа перейди в узкий треугольник у правой стенки. Его внешний проход ведёт к выходу 5."]],""],[822,138,"У Кати вчера был день рождения. Завтра будет пятница. В какой день недели был день рождения Кати?",{"0":[53.7,68.9,31.3,27.2],"1":[311.6,68.9,31.4,27.2],"2":[558,68.9,32.7,27.2],"3":[53.7,103,32.7,27.2],"4":[311.6,103,31.4,27.2]},"B","День рождения Кати",[["Определи сегодняшний день","Завтра пятница, значит, сегодня четверг."],["Отсчитай один день назад","Вчера была среда. На среду пришёлся день рождения Кати."]],""],[822,184,"Шесть городов соединены автобусными маршрутами. Стоимость проезда между этими городами указана на схеме. За какую наименьшую сумму можно проехать из города А в город В?",{"0":[53.7,150,31.3,27.2],"1":[158.4,150,31.3,27.2],"2":[265,150,32.6,27.2],"3":[371.6,150,32.6,27.2],"4":[478.1,150,31.3,27.2]},"C","Самый дешёвый маршрут",[["Найди первые пересадки","За 20 от А можно попасть в ближайший верхний город, а ещё за 10 — в следующий верхний. Оттуда до нижнего левого города ещё 30. Это 60 от А, дешевле прямого переезда за 80."],["Дойди до В","По низу остаётся заплатить 20 и 10. Весь путь стоит 20 + 10 + 30 + 20 + 10 = 90."],["Проверь другие подъезды","Последний переезд в В стоит 70 сверху или 10 снизу. До верхнего города нужно хотя бы 30, значит, сверху вышло бы не меньше 100. До нижнего правого города можно доехать за 60 + 20 = 80 через нижний левый или как минимум за 30 + 60 = 90 сверху."]],""],[843,137,"Если уменьшаемое уменьшить на 1, а из вычитаемого вычесть 1, то разность",{"0":[53.8,68.9,31.3,27.2],"1":[298.2,68.9,31.3,27.2],"2":[544.8,68.9,32.7,27.2],"3":[53.8,103,32.7,27.2],"4":[298.2,103,31.3,27.2]},"A","Оба числа уменьшились",[["Представь числа на линейке","Разность показывает, на сколько одно число больше другого. Сдвинь обе отметки на один шаг влево."],["Сравни расстояние","Обе отметки сдвинулись одинаково, поэтому расстояние между ними не изменилось. Разность осталась прежней."]],""],[843,212,"Коля играет на компьютере каждый день по 40 минут, а Вася – по 5 часов в неделю (больше родители не разрешают). Кому из мальчиков за неделю удается больше времени поиграть на компьютере и на сколько?",{"0":[53.8,118.2,31.3,27.2],"1":[411.5,118.2,31.4,27.2],"2":[53.7,147.5,32.7,27.2],"3":[411.5,147.5,32.7,27.2],"4":[53.7,176.9,31.4,27.2]},"B","Время за компьютером",[["Переведи всё в минуты","За семь дней Коля играет 7 × 40 = 280 минут. Вася играет 5 × 60 = 300 минут."],["Сравни результаты","300 − 280 = 20. Вася играет на 20 минут больше."]],""],[843,203,"На каком из квадратиков закрашена ровно одна треть клеточек?",{"0":[53.7,168.9,31.3,27.2],"1":[204.9,168.9,31.4,27.2],"2":[358.2,168.9,32.6,27.2],"3":[504.8,168.9,32.7,27.2],"4":[657.9,168.9,31.4,27.2]},"C","Треть квадрата",[["Найди одну треть","В каждом квадратике 3 × 3 = 9 клеток. Одна треть — это 9 : 3 = 3 клетки."],["Посчитай закрашенные клетки","В C закрашены две левые клетки сверху и одна правая снизу. В остальных квадратиках закрашенных клеток больше трёх."]],""],[843,101,"Петя прибавляет различные однозначные числа к числу 96. Сколько раз он получит трехзначное число?",{"0":[53.7,66.5,31.3,27.2],"1":[211.6,66.5,31.3,27.2],"2":[358.2,66.5,32.7,27.2],"3":[504.8,66.5,32.6,27.2],"4":[651.3,66.5,31.3,27.2]},"D","От 96 до 100",[["Найди первое трёхзначное число","Наименьшее трёхзначное число — 100. До него от 96 не хватает 4."],["Перебери подходящие слагаемые","Подходят однозначные числа 4, 5, 6, 7, 8 и 9. Это шесть разных случаев."]],""],[843,131,"На левой стороне улицы находятся дома с нечетными номерами от 1 до 19, а на правой стороне – дома с четными номерами от 2 до 14. Сколько домов на этой улице?",{"0":[53.7,95.9,31.3,27.2],"1":[211.6,95.9,31.3,27.2],"2":[358.2,95.9,32.6,27.2],"3":[504.8,95.9,32.6,27.2],"4":[651.3,95.9,31.3,27.2]},"B","Дома по обе стороны",[["Сосчитай нечётные номера","Слева номера идут от 1 до 19 через один. Номера 1, 3, 5, …, 19 дают десять домов."],["Сосчитай чётные номера","Справа идут 2, 4, 6, …, 14. Это семь домов. Всего 10 + 7 = 17."]],""],[843,157,"За квадратный столик могут сесть одновременно 4 гнома, по одному с каждой стороны. Для вечеринки 7 таких столиков составили в ряд (вплотную один к другому). Сколько гномов могут сесть за получившийся длинный стол?",{"0":[53.7,122.9,31.3,27.2],"1":[211.6,122.9,31.3,27.2],"2":[358.2,122.9,32.6,27.2],"3":[504.8,122.9,32.6,27.2],"4":[651.3,122.9,31.3,27.2]},"B","Длинный стол гномов",[["Посчитай места по длинным сторонам","Семь квадратных столиков в ряд образуют длинный прямоугольник. На каждой длинной стороне помещаются семь гномов."],["Добавь два торца","На каждом торце остаётся по одному месту, а у внутренних стыков мест нет. Всего 7 + 7 + 1 + 1 = 16."]],""],[843,157,"Самое маленькое число, которое можно получить, выкладывая в ряд карточки, изображенные справа, равно",{},"D","Наименьшее число из карточек",[["Выбери начало","Самое маленькое число должно начинаться с самой маленькой доступной цифры. Сначала клади карточку 2, затем 309. Теперь наименьшая первая цифра среди оставшихся — 4 на карточке 41."],["Продолжи тем же способом","Дальше идут карточки 5, 68 и 7. Цифры внутри каждой карточки идут вместе, поэтому получается 2 309 415 687."]],""],[822,130,"На стеклянной двери написано: «КЕНГУРУ ПРИГЛАШАЕТ ДРУЗЕЙ». Сколько из этих 23 букв выглядят одинаково с той и с другой стороны двери?",{"0":[53.7,96,31.3,27.2],"1":[211.6,96,31.3,27.2],"2":[358.2,96,32.6,27.2],"3":[504.8,96,32.6,27.2],"4":[651.2,96,31.3,27.2]},"C","Буквы на стекле",[["Представь зеркальное отражение","С другой стороны двери левое и правое в каждой букве поменяются местами. Одинаково выглядят буквы, у которых левая и правая половины зеркально совпадают."],["Посчитай симметричные буквы","В надписи это Н в слове КЕНГУРУ, П, Л, А, Ш, А, Т в слове ПРИГЛАШАЕТ и Д в слове ДРУЗЕЙ. Всего 1 + 6 + 1 = 8."]],""],[822,158,"Вороны Дана, Нана, Лана и Зана сидят на заборе. Дана сидит посредине между Наной и Ланой. Расстояние между Наной и Даной такое же, как между Ланой и Заной. Между Даной и Заной расстояние 4 метра. Какое расстояние между Наной и Заной?",{"0":[53.7,122.9,31.3,27.2],"1":[211.6,122.9,31.3,27.2],"2":[358.1,122.9,32.7,27.2],"3":[504.8,122.9,32.6,27.2],"4":[651.3,122.9,31.3,27.2]},"B","Вороны на заборе",[["Найди три равных промежутка","От Наны до Даны столько же, сколько от Даны до Ланы. От Ланы до Заны — ещё один такой же промежуток. Зана сидит по другую сторону от Ланы, чем Дана, иначе она оказалась бы на месте Даны."],["Восстанови длину одного промежутка","Между Даной и Заной два промежутка общей длиной 4 м. Один равен 2 м, а между Наной и Заной три таких промежутка, всего 6 м."]],""],[822,157,"Ваня стреляет в тире. Он заплатил за 10 выстрелов. За каждое попадание в мишень Ваня получает право на два дополнительных выстрела. Ему удалось сделать 20 выстрелов. Сколько раз Ваня попал в мишень?",{"0":[53.7,123,31.3,27.2],"1":[211.6,123,31.3,27.2],"2":[358.1,123,32.7,27.2],"3":[504.8,123,32.6,27.2],"4":[651.3,123,31.3,27.2]},"D","Попадания в тире",[["Найди число дополнительных выстрелов","Из двадцати выстрелов десять были оплачены. За попадания Ваня получил ещё 20 − 10 = 10 выстрелов."],["Раздели на пары","За каждое попадание дают два выстрела. Значит, попаданий было 10 : 2 = 5."]],""],[822,76,"Сколько получится, если 2 десятка умножить на 5 десятков?",{"0":[53.7,41.9,31.3,27.2],"1":[158.3,41.9,31.3,27.2],"2":[265,41.9,32.7,27.2],"3":[478.1,41.9,32.6,27.2],"4":[631.3,41.9,31.3,27.2]},"E","Произведение десятков",[["Запиши числа","Два десятка — это 20, а пять десятков — 50."],["Выполни умножение","20 × 50 = 1000. В тысяче десять сотен."]],""],[822,267,"У Глаши есть набор фигурок, белых с одной стороны и цветных – с другой. Глаша сложила из своих фигурок прямоугольник так, как изображено на рисунке. Какая из фигурок",{},"C","Фигурка со стороны цвета",[["Найди четыре детали","A после поворота лежит слева от центра, B — сверху ближе к середине и ещё раз справа от центра. D — крест в середине, а E после полуоборота находится вдоль левого края ниже середины."],["Проверь оставшийся силуэт","Слева внизу есть ступенька из пяти клеток, похожая на C. Все повороты C дают ступеньку другой формы. Чтобы она совпала, её пришлось бы перевернуть на цветную сторону. Среди белых деталей C нет."]],""],[822,138,"Если в некотором месяце 5 суббот, то в этом месяце не может быть",{"0":[53.7,68.9,31.3,27.2],"1":[311.6,68.9,31.3,27.2],"2":[558,68.9,32.7,27.2],"3":[53.7,103,32.6,27.2],"4":[311.6,103,31.3,27.2]},"A","Пять суббот",[["Отдели четыре недели","В каждом месяце есть четыре полные недели, то есть 28 дней. Остаётся не больше трёх дней подряд. Только дни недели из этого остатка встречаются пять раз."],["Сравни субботу со вторником","Суббота и вторник не помещаются в отрезок из трёх дней подряд. Даже если начать с субботы, вторник будет четвёртым днём. Поэтому пяти вторников быть не может."]],""],[822,130,"Электронные часы показывают часы и минуты (от 00:00 до 23:59). Сколько раз за сутки в наборе цифр на табло этих часов участвуют только цифры 2 и 5 (или одна из этих цифр)?",{"0":[53.7,96,31.3,27.2],"1":[211.6,96,31.3,27.2],"2":[358.2,96,32.7,27.2],"3":[504.8,96,32.6,27.2],"4":[651.3,96,31.3,27.2]},"C","Цифры на электронных часах",[["Выбери часы","На табло часы от 00 до 23. Из двоек и пятёрок можно записать только 22 в этих пределах."],["Выбери минуты","В первом и втором разрядах минут можно независимо поставить 2 или 5. Получаются 22:22, 22:25, 22:52 и 22:55. Всего четыре раза."]],""],[843,197,"Антон и Миша считают деревья, растущие вокруг пруда. Они двигаются в одном направлении, но начинают счет с разных деревьев. То дерево, которое Миша назвал двадцатым, для Антона оказалось четвертым, а дерево, которое Миша назвал десятым, для Антона оказалось сорок шестым. Сколько деревьев растет вокруг пруда?",{"0":[53.7,163,31.3,27.2],"1":[211.6,163,31.3,27.2],"2":[358.2,163,32.7,27.2],"3":[504.8,163,32.6,27.2],"4":[651.3,163,31.3,27.2]},"B","Деревья вокруг пруда",[["Сравни два отмеченных дерева","Миша от десятого дерева до двадцатого насчитал 10 шагов между деревьями. Для Антона это путь от 46-го дерева до 4-го через начало круга."],["Замкни круг","От первого дерева Антона до 4-го три шага. От 46-го дерева до первого остаётся 10 − 3 = 7 шагов. От первого до 46-го — 45 шагов. Во всём круге 45 + 7 = 52 дерева."]],""],[843,209,"На каждой из 7 карточек на верхнем рисунке написано по две буквы. На нижнем рисунке – те же карточки, но в другом порядке. Какое «слово» могло получиться внизу?",{"0":[53.7,145.2,31.3,27.2],"1":[278.2,145.2,31.4,27.2],"2":[53.7,174.6,32.7,27.2],"3":[278.2,174.6,32.7,27.2],"4":[544.7,174.6,31.3,27.2]},"D","Буквы на карточках",[["Сохрани пары","У каждой карточки при перестановке сохраняются обе буквы. Для верхней К снизу может стоять К или У, для О — Е, Г или Р, для Л — Н или У."],["Собери нижнюю строку","Для нижней надписи из D бери по порядку пары Л–У, О–Г, К–У, О–Р, Л–Н, О–Е и К–К. Все семь исходных карточек использованы по одному разу. Читается УГУРНЕК."]],""],[843,219,"Если лягушонок зеленый, то он веселый. Если лягушонок не веселый, то он сидит на берегу. Все лягушата либо зеленые, либо пестренькие. Если лягушонок пестренький, то он плавает в воде. Тогда обязательно",{"0":[53.7,120.6,31.4,27.2],"1":[431.5,120.6,31.4,27.2],"2":[53.7,152.3,32.7,27.2],"3":[431.5,152.3,32.7,27.2],"4":[53.7,184,31.4,27.2]},"C","Весёлые лягушата",[["Проверь зелёных","По условию любой зелёный лягушонок весёлый."],["Проверь пёстрых","Пёстрый лягушонок плавает в воде. Если бы он был невесёлым, то сидел бы на берегу. Значит, пёстрый тоже весёлый, а вместе это все лягушата."]],""],[843,191,"Кенгуру Попрыгун проснулся под пальмой и стал радостно скакать по дорожке, иногда меняя направление прыжков. Длина каждого его прыжка либо 2 метра, либо 4 метра, либо 7 метров. На каком расстоянии от пальмы он не мог оказаться после 10 прыжков?",{},"E","Десять прыжков",[["Получи 3 м и 49 м","Для 3 м сделай прыжок на 7 м от пальмы и на 4 м обратно, а ещё четыре пары прыжков по 2 м туда и обратно. Для 49 м прыгни семь раз по 7 м, затем на 2 м, ещё на 2 м и на 4 м обратно."],["Получи 61 м и 62 м","Девять прыжков по 7 м вперёд и один на 2 м назад дадут 61 м. Восемь прыжков по 7 м, один на 4 м и один на 2 м вперёд дадут 62 м. Для каждого расстояния получилось ровно 10 прыжков."]],""],[843,156,"",{},"C","Треугольники в треугольнике",[["Начни с крупных фигур","Есть один самый большой треугольник. Он разделён на четыре треугольника вдвое меньшего размера: три в углах и один перевёрнутый посередине."],["Посчитай следующие размеры","Каждый из трёх угловых треугольников разделён ещё на четыре, это 12 треугольников. Самый верхний из них снова разделён на четыре маленьких."],["Сложи результаты","По размерам получилось 1, 4, 12 и 4. Всего 1 + 4 + 12 + 4 = 21 треугольник."]],""],[843,128,"В ребусе КЕН × Г = УРУ одинаковыми буквами зашифрованы одинаковые цифры, а разными – разные. Если К равно 2, то У равно",{"0":[53.7,93.8,31.3,27.2],"1":[211.6,93.8,31.3,27.2],"2":[358.1,93.8,32.7,27.2],"3":[504.8,93.8,32.6,27.2],"4":[651.3,93.8,31.3,27.2]},"D","КЕН умножить на Г",[["Ограничь множитель","КЕН лежит между 200 и 299. При множителе 5 или больше ответ был бы четырёхзначным. Множитель 0 не годится, 1 дал бы У = К, а 2 уже занята буквой К. Остаются 3 и 4."],["Проверь умножение на 3","При множителе 3 первая и последняя цифры ответа могут быть 6, 7 или 8. При У = 6 последняя цифра КЕН — 2, уже занятая буквой К. При У = 7 кандидаты 239, 249 и 259 дают 717, 747 и 777, в каждом случае разные буквы получают одинаковую цифру. При У = 8 так же отпадают 276, 286 и 296 с ответами 828, 858 и 888."],["Проверь умножение на 4","Произведение трёхзначное и не меньше 800. Оно чётное, поэтому из 8 и 9 для У подходит только 8. Ребус действительно складывается: 217 × 4 = 868."]],""]]]];
globalThis.KENGURU_LEGACY_CONDITIONS = {"2006":{"1":{"question":"Вася поет слово КЕНГУРУ. Он тянет каждый гласный звук 5 секунд, а на каждый согласный тратит ровно 1 секунду. Сколько времени он поет это слово?","choices":["7 сек","17 сек","19 сек","29 сек","35 сек"]},"2":{"question":"Сколько кубиков вынули?","choices":["4","5","6","7","8"],"image":"assets/legacy-conditions/2006/task-02.webp","imageWidth":421,"imageHeight":152},"3":{"question":"В кошельке у Сергея три монеты: 5 рублей, 2 рубля и 1 рубль. Какую сумму он не сможет заплатить без сдачи?","choices":["3 рубля","4 рубля","6 рублей","7 рублей","8 рублей"]},"4":{"question":"Кенгуру прошел через лабиринт, в котором один вход и пять выходов. Его маршрут проходил только по треугольным комнатам. Где он вышел?","choices":["1","2","3","4","5"],"image":"assets/legacy-conditions/2006/task-04.webp","imageWidth":354,"imageHeight":250},"5":{"question":"У Кати вчера был день рождения. Завтра будет пятница. В какой день недели был день рождения Кати?","choices":["во вторник","в среду","в пятницу","в субботу","в воскресенье"]},"6":{"question":"Шесть городов соединены автобусными маршрутами. Стоимость проезда между этими городами указана на схеме. За какую наименьшую сумму можно проехать из города А в город В?","choices":["70","80","90","100","110"],"image":"assets/legacy-conditions/2006/task-06.webp","imageWidth":359,"imageHeight":176},"7":{"question":"Если уменьшаемое уменьшить на 1, а из вычитаемого вычесть 1, то разность","choices":["не изменится","увеличится на 1","уменьшится на 1","увеличится на 2","уменьшится на 2"]},"8":{"question":"Коля играет на компьютере каждый день по 40 минут, а Вася – по 5 часов в неделю (больше родители не разрешают). Кому из мальчиков за неделю удается больше времени поиграть на компьютере и на сколько?","choices":["Коле больше на 40 минут","Васе больше на 20 минут","Васе больше на 40 минут","Коле больше на 20 минут","поровну"]},"9":{"question":"На каком из квадратиков закрашена ровно одна треть клеточек?","image":"assets/legacy-conditions/2006/task-09.webp","imageWidth":935,"imageHeight":212},"10":{"question":"Петя прибавляет различные однозначные числа к числу 96. Сколько раз он получит трехзначное число?","choices":["3","4","5","6","7"]},"11":{"question":"На левой стороне улицы находятся дома с нечетными номерами от 1 до 19, а на правой стороне – дома с четными номерами от 2 до 14. Сколько домов на этой улице?","choices":["16","17","18","19","33"]},"12":{"question":"За квадратный столик могут сесть одновременно 4 гнома, по одному с каждой стороны. Для вечеринки 7 таких столиков составили в ряд (вплотную один к другому). Сколько гномов могут сесть за получившийся длинный стол?","choices":["14","16","21","24","28"]},"13":{"question":"Самое маленькое число, которое можно получить, выкладывая в ряд карточки, изображенные справа, равно","choices":["2 309 541 768","7 309 568 412","2 741 568 309","2 309 415 687","2 309 415 678"],"image":"assets/legacy-conditions/2006/manual-13.webp","imageWidth":200,"imageHeight":90},"14":{"question":"На стеклянной двери написано: «КЕНГУРУ ПРИГЛАШАЕТ ДРУЗЕЙ». Сколько из этих 23 букв выглядят одинаково с той и с другой стороны двери?","choices":["12","10","8","7","6"]},"15":{"question":"Вороны Дана, Нана, Лана и Зана сидят на заборе. Дана сидит посредине между Наной и Ланой. Расстояние между Наной и Даной такое же, как между Ланой и Заной. Между Даной и Заной расстояние 4 метра. Какое расстояние между Наной и Заной?","choices":["5 м","6 м","7 м","8 м","9 м"]},"16":{"question":"Ваня стреляет в тире. Он заплатил за 10 выстрелов. За каждое попадание в мишень Ваня получает право на два дополнительных выстрела. Ему удалось сделать 20 выстрелов. Сколько раз Ваня попал в мишень?","choices":["10","8","6","5","4"]},"17":{"question":"Сколько получится, если 2 десятка умножить на 5 десятков?","choices":["10","50","10 десятков","5 сотен","10 сотен"]},"18":{"question":"У Глаши есть набор фигурок, белых с одной стороны и цветных — с другой. Глаша сложила из своих фигурок прямоугольник так, как изображено на рисунке. Какая из фигурок (A) — (E) ей не понадобилась?","image":"assets/legacy-conditions/2006/manual-18.webp","imageWidth":538,"imageHeight":277},"19":{"question":"Если в некотором месяце 5 суббот, то в этом месяце не может быть","choices":["5 вторников","5 воскресений","5 четвергов","5 понедельников","5 пятниц"]},"20":{"question":"Электронные часы показывают часы и минуты (от 00:00 до 23:59). Сколько раз за сутки в наборе цифр на табло этих часов участвуют только цифры 2 и 5 (или одна из этих цифр)?","choices":["12","6","4","2","1"]},"21":{"question":"Антон и Миша считают деревья, растущие вокруг пруда. Они двигаются в одном направлении, но начинают счет с разных деревьев. То дерево, которое Миша назвал двадцатым, для Антона оказалось четвертым, а дерево, которое Миша назвал десятым, для Антона оказалось сорок шестым. Сколько деревьев растет вокруг пруда?","choices":["50","52","56","60","80"]},"22":{"question":"На каждой из 7 карточек на верхнем рисунке написано по две буквы. На нижнем рисунке – те же карточки, но в другом порядке. Какое «слово» могло получиться внизу?","choices":["НЕКУРУГ","УРУГКЕН","НРУГЕКУ","УГУРНЕК","НЕГРУКУ"],"image":"assets/legacy-conditions/2006/task-22.webp","imageWidth":359,"imageHeight":200},"23":{"question":"Если лягушонок зеленый, то он веселый. Если лягушонок не веселый, то он сидит на берегу. Все лягушата либо зеленые, либо пестренькие. Если лягушонок пестренький, то он плавает в воде. Тогда обязательно","choices":["все лягушата плавают в воде","все лягушата — не веселые","все лягушата — веселые","все лягушата — пестренькие","все веселые лягушата — зеленые"]},"24":{"question":"Кенгуру Попрыгун проснулся под пальмой и стал радостно скакать по дорожке, иногда меняя направление прыжков. Длина каждого его прыжка либо 2 метра, либо 4 метра, либо 7 метров. На каком расстоянии от пальмы он не мог оказаться после 10 прыжков?","image":"assets/legacy-conditions/2006/task-24.webp","imageWidth":698,"imageHeight":85},"25":{"question":"Сколько треугольников изображено на рисунке?","choices":["16","20","21","22","23"],"image":"assets/legacy-conditions/2006/task-25.svg","imageWidth":228,"imageHeight":199},"26":{"question":"В ребусе КЕН × Г = УРУ одинаковыми буквами зашифрованы одинаковые цифры, а разными — разные. Если К равно 2, то У равно","choices":["4","6","7","8","9"]}}};
'use strict';

(() => {
  const latin = ['A', 'B', 'C', 'D', 'E'];
  const cyrillic = ['А', 'Б', 'В', 'Г', 'Д'];
  const escape = value => String(value).replaceAll('&', '&amp;').replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;').replaceAll('"', '&quot;');
  const archive = globalThis.KENGURU_ARCHIVE ??= {};
  const source = 'assets/kenguru';
  const ink = '#173439';
  const teal = '#237e79';
  const mint = '#e5f2ea';
  const muted = '#e8eee8';
  const line = '#b3c6bf';
  const gold = '#f7dda8';

  const text = (x, y, value, size = 27, color = ink, anchor = 'middle') =>
    `<text x="${x}" y="${y}" fill="${color}" font-family="system-ui, sans-serif" font-weight="700" font-size="${size}" text-anchor="${anchor}" dominant-baseline="middle">${escape(value)}</text>`;
  const box = (x, y, w, h, fill, stroke = 'none', radius = 10) =>
    `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${radius}" fill="${fill}" stroke="${stroke}"/>`;
  const segment = (x1, y1, x2, y2, color, width = 3) =>
    `<path d="M${x1} ${y1} L${x2} ${y2}" fill="none" stroke="${color}" stroke-width="${width}" stroke-linecap="round"/>`;
  const dot = (x, y, radius, fill) => `<circle cx="${x}" cy="${y}" r="${radius}" fill="${fill}"/>`;
  const svg = (width, height, label, inside, className = 'legacy-scene') =>
    `<svg class="${className}" viewBox="0 0 ${width} ${height}" role="img" aria-label="${escape(label)}">${inside}</svg>`;
  const image = (url, width, height) => `<image href="${url}" width="${width}" height="${height}"/>`;
  const progress = (frame, end) => Math.max(0, Math.min(1, frame / end));

  function renderOriginal(url, width, height, label, mark, frame) {
    let focus = '';
    if (mark) {
      const [x, y, w, h] = mark;
      const dash = .68 + .32 * progress(frame, 8);
      focus = `<rect x="${x - 4}" y="${y - 2}" width="${w + 8}" height="${h + 4}" rx="4" fill="none" stroke="${teal}" stroke-width="4" pathLength="1" stroke-dasharray="${dash} 1"/>`;
    }
    return svg(width, height, label, image(url, width, height) + focus);
  }

  function crop(url, width, height, [sx, sy, sw, sh], x, y, w, h) {
    return `<svg x="${x}" y="${y}" width="${w}" height="${h}" viewBox="${sx} ${sy} ${sw} ${sh}" style="overflow:hidden">${image(url, width, height)}</svg>`;
  }

  function workedScene([height, drawing], label, answer) {
    const size = 720;
    const band = answer ? 51 : 0;
    const badge = answer
      ? box(16, height, size - 32, 42, mint, line) + text(size / 2, height + 21, `Ответ ${answer}`, 24, teal)
      : '';
    return svg(size, height + band, label, drawing + badge, 'legacy-scene legacy-worked-scene');
  }

  // Extract only equations that the author explicitly uses in this step. A
  // space can group thousands, so it must not split their numeric tokens.
  const number = String.raw`[−-]?\d+(?:[ \u00a0\u202f]\d{3}(?!\d))*(?:[.,]\d+)?`;
  const operator = String.raw`[+−–×·⋅*÷:/=<>≤≥-]`;
  const equation = new RegExp(String.raw`${number}(?:\s*${operator}\s*${number})+`, 'gu');
  const tokens = new RegExp(String.raw`^(${number})|(${operator})\s*(${number})`, 'gu');

  function equationsIn(message) {
    return [...message.matchAll(equation)].map(match => match[0])
      .filter(value => /[=<>≤≥]/u.test(value))
      .map(value => [...value.matchAll(tokens)].flatMap(([, first, sign, next]) => first ? [first] : [sign, next]));
  }

  function drawEquations(rows, frame) {
    const drawing = rows.map((parts, row) => {
      const current = Math.min(parts.length - 1, Math.floor(Math.max(0, frame - row * 4) / 2));
      const sizes = parts.map((part, i) => i % 2 ? 32 : Math.max(48, 23 + part.length * 17));
      const width = sizes.reduce((sum, w) => sum + w, 0);
      const factor = Math.min(640 / width, 1);
      let x = (720 - width * factor) / 2;
      const y = 15 + row * 75;
      return box(16, y, 688, 62, '#f6f8f3') + parts.map((part, i) => {
        const w = sizes[i] * factor;
        const highlight = current === i;
        const result = i === parts.length - 1;
        const plate = (i % 2 === 0 || highlight)
          ? box(x + 2, y + 7, w - 4, 48, highlight ? gold : result ? mint : '#fff', result ? teal : 'none') : '';
        const item = plate + text(x + w / 2, y + 31, part, 32 * factor, result ? teal : ink);
        x += w;
        return item;
      }).join('');
    }).join('');
    return [rows.length * 75 + 13, drawing];
  }

  // The checked statement and the worksheet choices are transcribed together.
  // For illustrated choices, the approach below uses the original artwork.
  const authored = {
    '2001/3': {
      question: 'У Йозефа было 7 палочек. Он разломал одну из них пополам. Сколько теперь у него палочек?',
      choices: ['5', '6', '7', '8', '9'],
      draw: drawSticks,
    },
    '2002/2': {
      question: 'Чему равно число 2 + 2 − 2 + 2 − 2 + 2 − 2 + 2 − 2 + 2?',
      choices: ['0', '2', '4', '12', '20'],
      draw: drawPairs,
    },
    '2003/3': {
      question: 'На какой картинке сердечки составляют ровно три четверти от общего числа фигурок?',
      crop: [73, 65, 662, 131],
      illustration: 'Пять рисунков с сердечками, ромбами и треугольниками, варианты от A до E',
      draw: drawHearts,
    },
    '2004/4': {
      question: 'Сережа шел по лестнице, шагая через ступеньку (первую ступеньку он пропустил). При этом он считал шаги: «Один, два, три…». После того, как он сказал «пять», оказалось, что осталась одна ступенька. Сколько всего ступенек на лестнице?',
      choices: ['5', '7', '9', '11', '12'],
      draw: drawStairs,
    },
    '2005/3': {
      illustration: 'Квадратная таблица с восемью кенгуру',
      draw: drawKangaroos,
    },
    '2006/10': {
      question: 'Петя прибавляет различные однозначные числа к числу 96. Сколько раз он получит трехзначное число?',
      choices: ['3', '4', '5', '6', '7'],
      draw: drawNumberLine,
    },
    '2007/1': {
      question: 'Сколько общих букв у слов КЕНГУРУ и МАТЕМАТИКА?',
      choices: ['1', '2', '3', '4', '5'],
      draw: drawLetters,
    },
    '2008/6': {
      question: 'В первом аквариуме на 12 рыбок больше, чем во втором. Сколько рыбок надо переселить из первого аквариума во второй, чтобы рыбок в них стало поровну?',
      choices: ['12', '8', '6', '4', '2'],
      draw: drawAquariums,
    },
    '2009/2': {
      question: '200 × 9 + 200 + 9 = ?',
      choices: ['418', '1909', '2009', '4018', '20009'],
    },
    '2010/2': {
      question: 'Дети измерили шагами длину дорожки. У Ани получилось 17 шагов, у Наташи 15, у Дениса 14, у Вани 13 и у Тани 12. Кто из этих детей имеет самый длинный шаг?',
      choices: ['Аня', 'Наташа', 'Денис', 'Ваня', 'Таня'],
      draw: (step, frame) => drawBars(
        ['Аня', 'Наташа', 'Денис', 'Ваня', 'Таня'], [17, 15, 14, 13, 12], step === 2 ? 4 : -1, frame),
    },
    '2011/3': {
      question: 'Через три с половиной часа отправляется поезд, на котором Сёма поедет к бабушке. Боясь проспать, он проснулся полтора часа назад. За сколько часов до отправления поезда Сёма проснулся?',
      choices: ['за полтора часа', 'за 2 часа', 'за 3 с половиной часа', 'за 4 часа', 'за 5 часов'],
      draw: (step, frame) => drawTimeline(
        ['Пробуждение', 'Сейчас', 'Отправление'], [1.5, 3.5], ['1,5 ч', '3,5 ч'], step === 2 ? '5 часов' : '', frame),
    },
    '2012/4': {
      question: 'Три воздушных шарика стоят на 12 рублей больше, чем один шарик. Сколько стоит один шарик?',
      choices: ['4 руб.', '6 руб.', '8 руб.', '10 руб.', '12 руб.'],
      draw: drawBalloons,
    },
    '2013/4': {
      question: 'Миша измерил длины пяти палочек и записал результаты этих измерений. Какой из результатов А–Д самый большой?',
      choices: ['3 дм 2 см', '3 см 7 мм', '35 мм', '3 см', '302 мм'],
      draw: (step, frame) => step === 1
        ? drawEquations(equationsIn('300 + 20 = 320'), frame)
        : drawBars(['А', 'Б', 'В', 'Г', 'Д'], [320, 37, 35, 30, 302], 0, frame, ' мм'),
    },
    '2014/1': {
      illustration: 'Буквы слова КЕНГУРУ, сложенные из палочек',
      draw: drawStickLetters,
    },
    '2015/2': {
      question: 'Чему равна сумма двадцати сотен и пятнадцати?',
      choices: ['35', '215', '2015', '20015', '200015'],
    },
    '2016/2': {
      question: 'Крошке Ру 17 марта исполняется 7 недель и 3 дня. Когда ему исполнится 9 недель?',
      choices: ['21 марта', '24 марта', '26 марта', '28 марта', '30 марта'],
      draw: (step, frame) => drawTimeline(
        ['17 марта', step === 2 ? '21 марта' : '8 недель', step === 2 ? '28 марта' : '9 недель'],
        [4, 7], ['4 дня', '7 дней'], step === 2 ? '11 дней' : '', frame),
    },
    '2017/1': {
      question: 'Кенга составила пять примеров на сложение. Какая сумма самая большая?',
      choices: ['2 + 0 + 1 + 7', '2 + 0 + 17', '20 + 17', '20 + 1 + 7', '201 + 7'],
      draw: drawSums,
    },
    '2018/3': {
      question: 'В Петербурге 15 марта в 16 часов пошел снег, а 16 марта в 15 часов снегопад закончился. Сколько часов он продолжался?',
      choices: ['11', '12', '23', '24', '25'],
      draw: (step, frame) => drawTimeline(
        step === 1 ? ['15 марта, 16:00', 'Полночь'] : ['15 марта, 16:00', 'Полночь', '16 марта, 15:00'],
        step === 1 ? [8] : [8, 15], step === 1 ? ['8 ч'] : ['8 ч', '15 ч'], step === 2 ? '23 часа' : '', frame, 23),
    },
    '2019/1': {
      question: 'В зоопарке 21 ноября 2018 года родился кенгуренок. Сколько месяцев ему исполнилось 21 марта 2019 года?',
      choices: ['3', '4', '5', '6', '7'],
      draw: (step, frame) => drawTimeline(
        step === 1 ? ['21 нояб.', '21 дек.', '21 янв.'] : ['21 нояб.', '21 дек.', '21 янв.', '21 февр.', '21 марта'],
        step === 1 ? [1, 1] : [1, 1, 1, 1], step === 1 ? ['1 мес.', '1 мес.'] : ['1 мес.', '1 мес.', '1 мес.', '1 мес.'],
        step === 2 ? '4 месяца' : '', frame, 4),
    },
  };

  function drawSticks(step, frame) {
    let drawing = '';
    for (let i = 0; i < 6; i++) drawing += segment(101 + i * 70, 38, 101 + i * 70, 117, teal, 11);
    drawing += text(275, 150, '6 целых', 26);
    const gap = step === 1 ? 0 : 20 + 9 * progress(frame, 8);
    drawing += segment(567 - gap, 38, 567 - gap, 74, '#bc6340', 11);
    drawing += segment(567 + gap, 82, 567 + gap, 117, '#bc6340', 11);
    drawing += text(567, 150, step === 1 ? 'сломанная' : '2 половины', 26);
    return [180, drawing];
  }

  function drawPairs(step, frame) {
    let drawing = box(17, 22, 119, 61, mint) + text(77, 52, '2 + 2', 30);
    const active = Math.min(3, Math.floor(Math.max(0, frame) / 4));
    for (let i = 0; i < 4; i++) {
      const x = 151 + 139 * i;
      drawing += box(x, 22, 130, 61, step === 1 && i === active ? gold : muted);
      drawing += text(x + 65, 52, step === 1 ? '−2 + 2' : '0', 30);
      if (step === 1) drawing += segment(x + 65, 89, x + 65, 111, teal) + text(x + 65, 137, '0', 26, teal);
    }
    if (step === 2) drawing += text(360, 137, '2 + 2 = 4', 33, teal);
    return [173, drawing];
  }

  function drawHearts(step, frame, card) {
    if (step === 1) {
      let drawing = '';
      for (let i = 0; i < 4; i++) {
        const x = 105 + i * 128;
        drawing += box(x, 40, 105, 81, i === 3 ? muted : mint, line);
        drawing += text(x + 52, 80, i === 3 ? '◇' : '♥', 49, i === 3 ? ink : '#a34849');
      }
      return [175, drawing + text(360, 145, '3 из 4', 30, teal)];
    }
    const [url, w, h] = card;
    const choiceImage = globalThis.KENGURU_CHOICE_LAYOUTS?.['2003-3-4/3']?.options[3]?.image;
    const drawing = choiceImage
      ? `<image href="${escape(choiceImage)}" x="251" y="11" width="228" height="240"/>`
      : crop(url, w, h, [493, 66, 76, 80], 251, 11, 228, 240);
    const alpha = .45 + progress(frame, 9) * .55;
    return [260, drawing +
      `<g opacity="${alpha}">` +
      box(256, 15, 216, 158, 'none', '#a34849') + box(256, 176, 216, 73, 'none', teal) +
      text(490, 94, '9 сердец', 27, '#a34849', 'start') +
      text(490, 206, '3 другие фигуры', 23, teal, 'start') + '</g>'];
  }

  function drawStairs(step, frame) {
    let drawing = '';
    for (let i = 1; i <= 11; i++) {
      const x = 26 + 60 * (i - 1);
      const y = 176 - 13 * (i - 1);
      const landed = i % 2 === 0;
      const active = landed && i / 2 === Math.min(5, 1 + Math.floor(Math.max(frame, 0) / 4));
      const remaining = i === 11 && step === 2;
      drawing += box(x, y, 59, 36, active ? gold : remaining || landed ? mint : muted, line, 4);
      if (i < 11 || remaining) drawing += text(x + 30, y + 18, i, 24, landed || remaining ? teal : ink);
      if (landed) drawing += dot(x + 30, y - 15, active ? 8 : 5, teal);
      if (remaining) drawing += text(x + 30, y - 20, '+1', 22, teal);
    }
    return [225, drawing];
  }

  function drawKangaroos(step, frame, figure) {
    const [url, w, h] = figure;
    const locations = [[0, 0], [0, 1], [1, 0], [1, 3], [2, 2], [2, 3], [3, 2], [1, 2]];
    let drawing = '';
    for (let row = 0; row < 4; row++) {
      for (let col = 0; col < 4; col++) {
        const fill = step === 1 && (row === 1 || col === 2) ? gold
          : row === 3 && col === 1 ? mint : '#fff';
        drawing += box(204 + col * 64, 14 + row * 64, 64, 64, fill, line, 0);
      }
    }
    const moving = step === 2 ? (frame === 0 ? 1 : progress(frame, 10)) : 0;
    if (step === 2 && frame > 0) {
      drawing += `<path d="M364 110 Q230 144 300 238" fill="none" stroke="${teal}" stroke-width="3" stroke-dasharray="7 5"/>`;
    }
    locations.forEach(([row, col], i) => {
      const active = i === locations.length - 1;
      const shift = active ? moving : 0;
      const x = 210 + col * 64 - shift * 64;
      const y = 21 + row * 64 + shift * 128 - 37 * Math.sin(shift * Math.PI);
      if (active) drawing += box(x - 3, y - 3, 58, 57, mint, teal, 7);
      drawing += `<svg x="${x}" y="${y}" width="52" height="50" viewBox="16 21 65 62" style="overflow:hidden;mix-blend-mode:multiply">${image(url, w, h)}</svg>`;
    });
    const counts = moving === 1 ? [2, 2, 2, 2] : moving === 0 ? [2, 3, 2, 1] : [2, 2, 2, 1];
    for (let i = 0; i < 4; i++) {
      drawing += text(489, 46 + i * 64, counts[i], 24, teal);
      drawing += text(236 + i * 64, 296, i === 1 ? counts[3] : i === 2 ? counts[1] : 2, 24, teal);
    }
    return [321, drawing];
  }

  function drawNumberLine(step, frame) {
    let drawing = segment(44, 99, 676, 99, line, 4);
    for (let i = 0; i < 10; i++) {
      const x = 45 + i * 70;
      const marked = i === 4 || (step === 2 && i > 4);
      const active = i === 4 + Math.min(step === 1 ? 0 : 5, Math.floor(Math.max(0, frame) / 3));
      if (marked) drawing += box(x - 28, 53, 56, 44, active ? gold : mint);
      drawing += text(x, 75, 96 + i, 23, marked ? teal : ink) + dot(x, 99, marked ? 6 : 4, marked ? teal : line);
      if (marked) drawing += text(x, 126, '+' + i, 20, teal);
    }
    return [155, drawing];
  }

  function drawLetters(step, frame) {
    const words = ['КЕНГУРУ', 'МАТЕМАТИКА'];
    const active = Math.min(words[0].length - 1, Math.floor(Math.max(0, frame) / 3));
    return [166, words.map((word, row) => [...word].map((letter, i) => {
      const x = 360 - word.length * 32 + i * 64;
      const y = 19 + row * 67;
      const common = step === 2 && 'КЕ'.includes(letter);
      const comparable = step === 1 && (row === 0 ? i === active : letter === words[0][active]);
      return box(x, y, 56, 54, common ? mint : comparable ? gold : muted, common ? teal : line) +
        text(x + 28, y + 27, letter, 30, common ? teal : ink);
    }).join('')).join('')];
  }

  function drawAquariums(step, frame) {
    const moved = step === 1 ? 1 : 6;
    const now = frame === 0 ? moved : Math.min(moved, 1 + Math.floor(frame / 3));
    let drawing = '';
    for (let tank = 0; tank < 2; tank++) {
      const x = 21 + tank * 365;
      drawing += box(x, 18, 313, 128, mint, line);
      drawing += text(x + 156, 40, tank ? 'Второй аквариум' : 'Первый аквариум', 22);
      drawing += text(x + 40, 96, '□ +', 25, teal);
      for (let i = 0; i < (tank ? now : 12 - now); i++) {
        drawing += dot(x + 81 + (i % 6) * 36, 81 + Math.floor(i / 6) * 33, 11, tank ? '#bc6340' : teal);
      }
    }
    drawing += text(360, 82, '→', 27, ink);
    const difference = now === 6 ? '6 = 6' : `${12 - now} − ${now} = ${12 - 2 * now}`;
    drawing += text(360, 174, difference, 29, teal);
    return [197, drawing];
  }

  function drawBars(names, values, highlighted, frame, unit = '') {
    const max = Math.max(...values);
    const active = Math.min(values.length - 1, Math.floor(Math.max(0, frame) / 3));
    let drawing = '';
    for (let i = 0; i < values.length; i++) {
      const y = 12 + i * 46;
      const w = values[i] / max * 450;
      drawing += text(124, y + 17, names[i], 22, ink, 'end');
      drawing += box(146, y, w, 34, i === highlighted ? teal : i === active ? gold : muted, line, 7);
      drawing += text(156 + w, y + 17, values[i] + unit, 22, i === highlighted ? teal : ink, 'start');
    }
    return [values.length * 46 + 6, drawing];
  }

  function drawTimeline(labels, sizes, durations, total, frame, span = sizes.reduce((sum, size) => sum + size, 0)) {
    const active = Math.min(sizes.length - 1, Math.floor(Math.max(0, frame) / 6));
    let x = 103;
    let drawing = '';
    sizes.forEach((size, i) => {
      const end = x + 514 * size / span;
      drawing += segment(x, 65, end, 65, i === active ? '#c07848' : teal, 8);
      drawing += dot(x, 65, 8, teal);
      drawing += text(x, 100, labels[i], 21);
      drawing += text((x + end) / 2, 34, durations[i], 25, teal);
      x = end;
    });
    drawing += dot(x, 65, 8, teal) + text(x, 100, labels.at(-1), 21);
    if (total) drawing += box(103, 129, 514, 40, mint) + text(360, 149, total, 26, teal);
    return [total ? 183 : 128, drawing];
  }

  function drawBalloons(step, frame) {
    const active = Math.min(2, 1 + Math.floor(Math.max(0, frame) / 4));
    let drawing = segment(343, 62, 586, 62, teal, 3) + text(464, 36, '12 руб.', 26, teal);
    for (let i = 0; i < 3; i++) {
      const x = 175 + i * 144;
      const color = i === 0 ? '#a9b9b2' : i === active ? '#bc6340' : teal;
      drawing += dot(x, 118, 38, color);
      drawing += box(x - 6, 151, 12, 12, color, 'none', 0);
      drawing += segment(x, 162, x, 181, color);
      drawing += text(x, 207, i === 0 ? 'вычитаем' : step === 1 ? '?' : '6 руб.', 25, color);
      if (i === 0) drawing += segment(x - 45, 165, x + 45, 77, '#7d4940', 4);
    }
    return [239, drawing];
  }

  function drawStickLetters(step, frame, figure) {
    const [url, w, h] = figure;
    const sources = [[7, 43], [57, 57], [123, 60], [193, 56], [253, 53], [313, 62], [380, 58]];
    const values = [4, 5, 5, 3, 3, 5, 3];
    const active = Math.min(6, Math.floor(Math.max(0, frame) / 3));
    let drawing = '';
    for (let i = 0; i < sources.length; i++) {
      const [sx, sw] = sources[i];
      const x = 24 + i * 98;
      const relevant = step === 2 ? values[i] === 5 : values[i] !== 5;
      drawing += box(x, 21, 85, 126, relevant ? mint : muted, relevant ? teal : line);
      const letterWidth = sw * 77 / 100;
      drawing += crop(url, w, h, [sx, 3, sw, 100], x + (85 - letterWidth) / 2, 30, letterWidth, 77);
      if (relevant) drawing += text(x + 43, 125, values[i], 24, active === i ? '#a24d36' : teal);
    }
    return [167, drawing];
  }

  function drawSums(step, frame) {
    if (step === 2) return drawBars(['А', 'Б', 'В', 'Г', 'Д'], [10, 19, 37, 28, 208], 4, frame);
    const expressions = authored['2017/1'].choices;
    const drawing = expressions.map((value, i) => {
      const x = 12 + i * 140;
      return box(x, 25, 135, 61, i === 4 ? mint : muted, i === 4 ? teal : line) +
        text(x + 67, 55, value, 22, i === 4 ? teal : ink);
    }).join('');
    return [113, drawing];
  }

  for (const [year, label, tasks] of globalThis.KENGURU_LEGACY ?? []) {
    const letters = year < 2008 ? latin : cyrillic;
    const lessons = [];
    const scenes = [];
    for (const [i, [width, height, , marks, key, name, explanation, note]] of tasks.entries()) {
      const number = i + 1;
      const answer = key === '?' ? null : latin.indexOf(key);
      const originalImage = `assets/years/${year}/task-${String(number).padStart(2, '0')}.webp`;
      const card = [originalImage, width, height];
      const authoredTask = authored[year + '/' + number];
      const imported = globalThis.KENGURU_LEGACY_CONDITIONS?.[year]?.[number];
      const native = authoredTask?.question ? authoredTask : imported ?? authoredTask;
      const figure = native === imported && imported?.image
        ? [imported.image, imported.imageWidth, imported.imageHeight] : null;
      const illustration = figure
        ? svg(imported.imageWidth, imported.imageHeight, authoredTask?.illustration ?? 'Рисунки и варианты из условия',
            image(escape(imported.image), imported.imageWidth, imported.imageHeight))
          .replace('<svg ', `<svg style="max-width:${imported.imageWidth}px" `)
        : '';
      const steps = [
        ['Твоё решение', 'Условие задачи', 'Выбери свой вариант ответа.'],
        ...explanation.map(([heading, message], stage) => [
          stage === explanation.length - 1 ? 'Ответ' : 'Шаг ' + (stage + 1), heading, message,
        ]),
      ];
      const formulas = explanation.map(([, message]) => equationsIn(message));
      const choice = answer === null ? '' : letters[answer];
      const description = `Условие и варианты задачи ${number} из оригинала.`;
      lessons.push({
        number,
        title: name,
        short: name,
        skill: '',
        answer,
        choices: native?.choices ?? ['', '', '', '', ''],
        choiceImages: native?.choiceImages,
        question: native?.question ?? '',
        conditionImage: figure?.[0],
        questionNote: note,
        legacyOriginal: true,
        hideIntroText: Boolean(native),
        showCompletedStep: true,
        points: i < 10 ? 3 : i < 20 ? 4 : 5,
        originalImage,
        steps,
      });
      scenes.push((step, frame) => {
        if (step === 0 && authoredTask?.crop) {
          const region = authoredTask.crop;
          const cropHeight = Math.round(720 * region[3] / Math.max(600, region[2]));
          const cropWidth = cropHeight * region[2] / region[3];
          return svg(720, cropHeight, authoredTask.illustration,
            crop(...card, region, (720 - cropWidth) / 2, 0, cropWidth, cropHeight));
        }
        if (step === 0 && native) return illustration;
        const final = step === steps.length - 1;
        const revealed = final ? choice : '';
        const answerLabel = revealed ? ` Ответ ${revealed}.` : '';
        if (step > 0) {
          const content = authoredTask?.draw
            ? authoredTask.draw(step, frame * 3, figure ?? card)
            : formulas[step - 1].length ? drawEquations(formulas[step - 1], frame * 5) : null;
          if (content) return workedScene(content, steps[step][1] + '. ' + steps[step][2] + answerLabel, revealed);
          if (native) {
            if (!revealed) return '';
            return workedScene([0, ''], description + answerLabel, revealed);
          }
        }
        return renderOriginal(...card, description + answerLabel, final ? marks[answer] : null, frame);
      });
    }

    archive[year] = {
      year,
      id: year + '-3-4',
      grades: [3, 4],
      label,
      answerLetters: letters,
      sources: {
        tasksUrl: `${source}/kenguru_${year}_class_3-4.pdf`,
        answersUrl: `${source}/kenguru_${year}_answers${[2017, 2018].includes(year) ? '-reviewed' : ''}.pdf`,
        solutionUrl: null,
      },
      lessons,
      scenes,
    };
  }
})();

